INSERT INTO book_author (book_id, author_id)
SELECT b.id, a.id FROM (VALUES
    ('pride-and-prejudice', 'Jane Austen'),
    ('frankenstein', 'Mary Shelley'),
    ('dracula', 'Bram Stoker'),
    ('moby-dick', 'Herman Melville'),
    ('alices-adventures-in-wonderland', 'Lewis Carroll'),
    ('the-adventures-of-sherlock-holmes', 'Arthur Conan Doyle'),
    ('meditations', 'Marcus Aurelius'),
    ('jane-eyre', 'Charlotte Bronte')
) AS m (book_slug, author_name)
JOIN book b ON b.slug = m.book_slug
JOIN author a ON a.name = m.author_name;

INSERT INTO book_category (book_id, category_id)
SELECT b.id, c.id FROM (VALUES
    ('pride-and-prejudice', 'classics'), ('pride-and-prejudice', 'romance'),
    ('frankenstein', 'classics'), ('frankenstein', 'science-fiction'),
    ('dracula', 'classics'), ('dracula', 'mystery-thriller'),
    ('moby-dick', 'classics'), ('moby-dick', 'fiction'),
    ('alices-adventures-in-wonderland', 'fantasy'), ('alices-adventures-in-wonderland', 'classics'),
    ('the-adventures-of-sherlock-holmes', 'mystery-thriller'),
    ('meditations', 'philosophy'), ('meditations', 'self-development'),
    ('jane-eyre', 'romance'), ('jane-eyre', 'classics')
) AS m (book_slug, category_slug)
JOIN book b ON b.slug = m.book_slug
JOIN category c ON c.slug = m.category_slug;

-- Printed edition for every book, e-book edition for most.
INSERT INTO product (book_id, sku, format, price, stock_quantity)
SELECT b.id, 'BK-' || upper(left(replace(b.slug, '-', ''), 8)) || '-PB', 'PAPERBACK',
       (ARRAY[39.90, 44.90, 49.90, 54.90, 59.90])[1 + (b.id % 5)], 10 + (b.id * 7 % 40)
FROM book b;

INSERT INTO product (book_id, sku, format, price, stock_quantity)
SELECT b.id, 'BK-' || upper(left(replace(b.slug, '-', ''), 8)) || '-EP', 'EPUB',
       (ARRAY[9.90, 12.90, 14.90, 19.90])[1 + (b.id % 4)], 0
FROM book b
WHERE b.slug <> 'moby-dick';
